difference() {
    cube([width, depth, thickness]);
    difference() {
        translate([margin, margin, thickness - groove_d])
            cube([width - 2 * margin, depth - 2 * margin, groove_d + 1]);
        translate([margin + groove_w, margin + groove_w, thickness - groove_d - 1])
            cube([
                width - 2 * (margin + groove_w),
                depth - 2 * (margin + groove_w),
                groove_d + 3
            ]);
    }
    for (x = [margin / 2 + 1, width - margin / 2 - 1],
         y = [margin / 2 + 1, depth - margin / 2 - 1])
        translate([x, y, -1]) cylinder(h = thickness + 2, d = hole_d);
}

// Spur gear, module 1, 25 teeth.
$fn = 64;
module_mm = 1;
teeth = 25;
face_w = 11;
bore_d = 5;
pitch_r = module_mm * teeth / 2;
root_r = pitch_r - 1.25 * module_mm;
tooth_t = module_mm * 1.6;

difference() {
    union() {
        cylinder(h = face_w, r = root_r);
        for (i = [0 : teeth - 1])
            rotate([0, 0, i * 360 / teeth])
                hull() {
                    translate([root_r, 0, 0])
                        cylinder(h = face_w, d = tooth_t);
                    translate([pitch_r + module_mm, 0, 0])
                        cylinder(h = face_w, d = tooth_t * 0.55);
                }
    }
    translate([0, 0, -1]) cylinder(h = face_w + 2, d = bore_d);
    translate([bore_d / 2 - 0.4, -1.5, -1])
        cube([1.8, 3.0, face_w + 2]);
}

